import {captureCalculation,RELEASE} from './material-notebook.js?v=20261110-en1';
import {esc,num,table,notes,sources,defaultInputs,controlsHTML,readControls,resultHTML,bindResult} from './spectroscopy-views.js?v=20261110-en1';
import {renderResponseProjects} from './response-projects.js?v=20261110-en1';
const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
const options=(rows,v)=>rows.map(([id,title])=>`<option value="${esc(id)}" ${String(id)===String(v)?'selected':''}>${esc(title)}</option>`).join('');
let catalogPromise,lastResult=null;
const catalog=()=>catalogPromise??=fetch('data/spectroscopy-materials.json?v='+RELEASE).then(r=>{if(!r.ok)throw Error("Magnetic Resonance, Superconducting Junction and multiplet Spectroscopy Course has not been loaded yet");return r.json();}).catch(e=>{catalogPromise=null;throw e;});
export const getSpectroscopyResult=()=>lastResult;
export const spectroscopyCourseRoute=(id,query='')=>'#classroom/'+({resonance:'spin',andreev:'spin',spectra:'observables'}[id]||'spin')+'?module='+id+(query?'&'+query:'');
const select=(label,key,rows,value)=>`<label>${esc(label)}<select id="spx-${key}">${options(rows,value)}</select></label>`;
const defaults=defaultInputs;
export async function renderSpectroscopyView({container,selection={},run,cancelRun,download,onNavigate=()=>{},onLocation=()=>{}}){
 container.innerHTML="<div class=\"obs-page qm-page response-page spectroscopy-page\"><p role=\"status\">is preparing courses on magnetic resonance, superconducting junctions and multiplet spectroscopy…</p></div>";
 const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;lastResult=null;
 let data;try{data=await catalog();}catch(e){if(current())root.innerHTML=`<p role="alert">${esc(e.message)}</p>`;return;}if(!current())return;
 let module=data.modules.find(m=>m.id===selection.module)||data.modules[0],lesson=data.lessons.find(l=>l.id===selection.lesson&&l.module===module.id)||data.lessons.find(l=>l.module===module.id),exercise=data.exercises.find(e=>e.id===selection.exercise&&e.module===module.id)||data.exercises.find(e=>e.lesson===lesson.id),tab=selection.calculationOnly?'lab':selection.atlasOnly?'cases':['learn','lab','derive','cases','project'].includes(selection.tab)?selection.tab:'learn';
 if(selection.exercise)lesson=data.lessons.find(l=>l.id===exercise.lesson)||lesson;
 const forms=structuredClone(defaults),material=data.cases.find(c=>c.id===selection.material&&c.module===module.id);let preset=selection.preset||material?.preset||'';
 const applyPreset=id=>{const p=module.presets.find(p=>p.id===id);if(p){forms[module.id]={...structuredClone(defaults[module.id]),...structuredClone(p.input)};if(p.input.data)forms[module.id].content=JSON.stringify(p.input.data,null,2);preset=p.id;}};applyPreset(preset);
 let result=null,busy=false,ticket=0,progress={};try{const p=JSON.parse(localStorage.getItem('symmetry-lab.spectroscopy.progress.v1')||'{}');if(object(p))progress=p;}catch{}
 const sync=()=>onNavigate({module:module.id,tab,lesson:lesson.id,exercise:tab==='derive'?exercise.id:undefined,material:selection.material,preset});
 const context=()=>new URLSearchParams({module:module.id,...(selection.material?{material:selection.material}:{}),...(preset?{preset}:{})}).toString();
 const links=()=>`<div class="obs-links"><a href="${spectroscopyCourseRoute(module.id,(selection.material?'material='+encodeURIComponent(selection.material)+'&':'')+(preset?'preset='+encodeURIComponent(preset):''))}">Course and Derivation →</a><a href="#atlas/spectroscopy?${esc(context())}">Material and model case →</a><a href="#atlas/projects?module=${module.id}">Cross-module project work →</a><a href="#atlas/notebook">Save material research records →</a></div>`;
 function invalidate(message="Parameters have changed, please run calculations to update the graph."){ticket++;result=null;lastResult=null;if(busy){cancelRun?.();busy=false;}if($('#spx-result'))$('#spx-result').innerHTML=`<p role="status">${esc(message)}</p>`;if($('#spx-run'))$('#spx-run').disabled=false;}
 function draw(){if(!current())return;onLocation((selection.calculationOnly?"Computing Center / ":selection.atlasOnly?"group and material map / ":"Learning center / ")+module.title);root.innerHTML=`<header class="obs-header"><span class="obs-eyebrow">RESONANCE · ANDREEV · POLARIZED XAS</span><h2>${selection.atlasOnly?"From Symmetry to Magnetic Resonance, Superconducting Junctions and multiplet Spectral Signals":esc(module.title)}</h2><p>${selection.atlasOnly?"Authentic material context and verifiable teaching models are interconnected.":esc(module.summary)}</p></header>${selection.calculationOnly||selection.atlasOnly?'':`<nav class="obs-tabs" aria-label="Magnetic Resonance, Superconducting Junction and multiplet Spectroscopy Class">${[['learn',"course explanation"],['lab',"Interactive experiments"],['derive',"Guided exercises"],['cases',"Material case studies"],['project',"project work"]].map(([id,t])=>`<button type="button" data-spx-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${t}</button>`).join('')}</nav>`}<div id="spx-content"></div>`;root.querySelectorAll('[data-spx-tab]').forEach(b=>b.onclick=()=>{invalidate();tab=b.dataset.spxTab;draw();sync();});if(tab==='learn')learn();else if(tab==='derive')derive();else if(tab==='cases')cases();else if(tab==='project')renderResponseProjects({container:$('#spx-content'),selection:{project:selection.project,module:module.id},download});else lab();}
 function learn(){$('#spx-content').innerHTML=`${select("Select theme",'lesson',data.lessons.filter(l=>l.module===module.id).map(l=>[l.id,l.title]),lesson.id)}<article class="obs-lesson"><h2>${esc(lesson.title)}</h2><p class="obs-lead">${esc(lesson.summary)}</p>${lesson.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.formula?`<div class="obs-formula">${esc(s.formula)}</div>`:''}</section>`).join('')}<div class="obs-links"><button id="spx-to-lab" class="primary">Open the corresponding experiment →</button><button id="spx-to-derive" class="secondary">step-by-step derivation →</button></div>${links()}${sources(data.sources.filter(s=>lesson.references.includes(s.id)))}</article>`;$('#spx-lesson').onchange=e=>{lesson=data.lessons.find(l=>l.id===e.target.value);exercise=data.exercises.find(e=>e.lesson===lesson.id);draw();sync();};$('#spx-to-lab').onclick=()=>{applyPreset(lesson.preset);invalidate();tab='lab';draw();sync();};$('#spx-to-derive').onclick=()=>{exercise=data.exercises.find(e=>e.lesson===lesson.id);tab='derive';draw();sync();};}
 function cases(){$('#spx-content').innerHTML=`<div class="obs-case-grid">${data.cases.filter(c=>selection.atlasOnly||c.module===module.id).sort((a,b)=>(b.id===selection.material)-(a.id===selection.material)).map(c=>{const m=data.modules.find(m=>m.id===c.module),q=new URLSearchParams({material:c.id,preset:c.preset}).toString();return `<article><span class="obs-eyebrow">${esc(c.kind)}</span><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p>${notes([c.assumption])}<div class="obs-links"><a href="${spectroscopyCourseRoute(c.module,q)}">Learning and Derivation →</a><a href="#compute/${m.route}?${q}">Open the corresponding calculation →</a>${c.links.filter(([,url])=>url!=='#atlas/notebook').map(([title,url])=>`<a href="${esc(url)}">${esc(title)} →</a>`).join('')}<a href="#atlas/notebook">Research Record →</a></div></article>`;}).join('')}</div>`;}
 function derive(){let step=0;const list=data.exercises.filter(e=>e.module===module.id);$('#spx-content').innerHTML=`${select("Select step-by-step exercises",'exercise',list.map(e=>[e.id,(progress[e.id]?'✓ ':'')+e.title]),exercise.id)}<article class="obs-lesson"><h2>${esc(exercise.title)}</h2><p>${esc(exercise.prompt)}</p><div id="spx-steps"></div><p id="spx-progress" role="status"></p>${links()}</article>`;$('#spx-exercise').onchange=e=>{exercise=list.find(x=>x.id===e.target.value);lesson=data.lessons.find(l=>l.id===exercise.lesson);draw();sync();};function next(){const s=exercise.steps[step],el=document.createElement('section');el.className='obs-exercise-step';el.innerHTML=`<h3>No. ${step+1} / ${exercise.steps.length} steps</h3><p>${esc(s.prompt)}</p><details><summary>View tips</summary><p>${esc(s.hint)}</p></details><div class="mr-choices">${s.choices.map((c,i)=>`<button type="button" class="secondary" data-spx-answer="${i}">${esc(c)}</button>`).join('')}</div><p class="obs-feedback" role="status"></p>`;$('#spx-steps').appendChild(el);el.querySelectorAll('[data-spx-answer]').forEach(b=>b.onclick=()=>{if(+b.dataset.spxAnswer!==s.answer){el.querySelector('.obs-feedback').textContent="Think again:"+s.hint;return;}el.querySelector('.obs-feedback').textContent='✓ '+s.explanation;el.querySelectorAll('button').forEach(b=>b.disabled=true);step++;if(step<exercise.steps.length)next();else{progress[exercise.id]=true;try{localStorage.setItem('symmetry-lab.spectroscopy.progress.v1',JSON.stringify(progress));}catch{}$('#spx-progress').textContent="✓ Derivation completed. Please go to the experiment to change the parameters and test this conclusion.";}});}next();}

 function lab(){
  $('#spx-content').innerHTML=`<div class="qm-lab"><form id="spx-form" class="obs-controls">${select("teaching default",'preset',[['',"Custom/current parameters"],...module.presets.map(p=>[p.id,p.title])],preset)}${controlsHTML(module.id,forms[module.id])}<button id="spx-run" type="submit" class="primary">Calculate and update the demo</button><button id="spx-cancel" type="button" class="secondary">Cancel calculation</button><p id="spx-status" role="status">Python runs locally in the browser.</p></form><section id="spx-result" class="qm-results" aria-live="polite"><div class="qm-welcome"><h3>Start with a preset</h3><p>Adjust parameters, compare physical response and numerical verification, and then include the results in project work.</p></div></section></div>${links()}`;
  const form=$('#spx-form');form.onsubmit=e=>{e.preventDefault();calculate();};
  form.oninput=e=>{if(e.target.id==='spx-preset')return;invalidate();
   if(module.id==='andreev'&&['spx-sites','spx-barrierStart'].includes(e.target.id)){
    const count=Number($('#spx-sites').value);if(Number.isInteger(count)&&count>=2&&count<=32){
     const start=$('#spx-barrierStart');start.max=count-1;start.value=Math.min(Number(start.value),count-1);
    }
   }
   try{forms[module.id]=readControls(module.id,root,forms[module.id]);}catch{}preset='';$('#spx-preset').value='';
  };
  $('#spx-preset').onchange=e=>{invalidate();applyPreset(e.target.value);draw();sync();};
  $('#spx-cancel').onclick=()=>{invalidate("The calculation has been cancelled. You can modify the parameters and rerun it.");$('#spx-status').textContent="Canceled";};
  if(result)renderResult();
 }
 async function calculate(){if(busy)return;let input;
  try{input=structuredClone(readControls(module.id,root,forms[module.id]));forms[module.id]=structuredClone(input);}catch(e){$('#spx-result').textContent=e.message;return;}
  const id=++ticket;busy=true;result=null;lastResult=null;$('#spx-run').disabled=true;$('#spx-status').textContent="is calculating...";$('#spx-result').innerHTML="<p role=\"status\">Running Python and checking numerical results...</p>";
  try{const output=await run(module.action,input);if(!current()||id!==ticket||tab!=='lab')return;result=output;lastResult={module:module.id,input:structuredClone(input),result:output};
   const route=selection.calculationOnly?'compute/'+module.route+(context()?'?'+context():''):spectroscopyCourseRoute(module.id).slice(1);captureCalculation(module.action,input,output,{route,title:module.title,material:selection.material||''});
   $('#spx-status').textContent="calculation completed · Can be exported or included in project operations";renderResult();
  }catch(e){if(current()&&id===ticket){$('#spx-result').textContent=e.message;$('#spx-status').textContent="The calculation is not completed, please check the parameters";}}
  finally{if(current()&&id===ticket){busy=false;if($('#spx-run'))$('#spx-run').disabled=false;}}
 }
 function renderResult(){$('#spx-result').innerHTML=`<div class="qm-result-heading"><span class="tag">Browser Python Results</span><button id="spx-export" type="button" class="secondary">export complete JSON</button></div>${resultHTML(module.id,result)}<a href="#atlas/projects?module=${module.id}">includes calculations into cross-module projects →</a>`;bindResult(module.id,result,root);$('#spx-export').onclick=()=>download?.(JSON.stringify(lastResult,null,2),module.id+'-result.json','application/json');}
 draw();
}
